import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2021-11-18","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-11-18","date":"2021-11-18T00:00:00.000Z","updated":"2021-11-20T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","性能优化","稳定性","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-11-18.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-11-18.md","lastUpdated":1780460162000}'),t={name:"posts/2021/Ceph_Performance_Meeting_2021-11-18.md"};function r(n,e,s,h,u,p){return l(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2021年11月18日，会议持续约1小时。</li><li><strong>参与者</strong>: 来自Ceph社区的开发商和用户，包括Jonas、Josh、Mark、Patrick等。</li><li><strong>会议目的</strong>: 讨论Ceph存储系统的最新开发进展，特别是关于分布式存储平衡器的工作。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Pull Requests (PRs) 更新</strong>:</p><ul><li>本周有两个新的PRs，一个是Josh Solomon提交的文档PR，另一个是Patrick提交的MDS相关PR。</li><li>一个关于请求超时优化的PR被合并。</li></ul></li><li><p><strong>Ceph Balancer 讨论</strong>:</p><ul><li>Jonas介绍了他的独立Ceph平衡器工作，该平衡器使用外部Python脚本通过Z API进行操作。</li><li>讨论了平衡器在处理不均匀设备大小和集群性能优化方面的挑战和解决方案。</li><li>Jonas的平衡器专注于通过移动PG（Placement Groups）来优化最满的OSD（Object Storage Daemon），以提高集群的整体平衡。</li></ul></li><li><p><strong>性能与稳定性问题</strong>:</p><ul><li>讨论了Ceph在处理大量PG时的性能问题，特别是关于PG分配和OSD的限制。</li><li>提到了一些长期存在的bug，如重新映射数据的问题，以及如何更好地处理这些bug。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了Jonas的平衡器工作的有效性，并讨论了将其集成到Ceph主分支的可能性。</li><li>讨论了改进Ceph平衡器的方法，包括增加对实际利用率而不是仅PG数量的考虑。</li><li>确定了需要进一步研究和解决的性能和稳定性问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和测试Jonas的平衡器，探索将其正式集成到Ceph的可能性和方法。</li><li>对现有的Ceph平衡器进行代码审查和性能优化，特别是在处理PG分配和OSD限制方面。</li><li>社区成员将继续跟踪和解决已知的bug和性能问题，特别是那些影响用户日常操作的问题。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到了Ceph社区对新功能开发和bug修复之间的平衡问题，强调了稳定性优化的重要性。</li><li>讨论了Ceph在不同使用场景下的适应性和优化策略，特别是在处理大型和异构集群时。</li></ul><h3 id="分析和改进" tabindex="-1">分析和改进 <a class="header-anchor" href="#分析和改进" aria-label="Permalink to &quot;分析和改进&quot;">​</a></h3><ol><li><strong>准确性</strong>: 改进后的总结准确反映了原始内容的要点，包括会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li><li><strong>错误和遗漏</strong>: 原始总结中遗漏了一些细节，如Jonas的平衡器如何处理不同大小的OSD以及如何平衡不同池中的数据。改进后的总结补充了这些信息。</li><li><strong>关键词</strong>: 改进后的总结保留了所有相关的Ceph相关领域的英文原文关键词，如Ceph、分布式存储、CRUSH算法、高可用性、可伸缩性、对象存储、块存储、文件系统存储、一致性、去中心化、性能、bluestore、bluefs、rocksdb、OSD、MON、MDS、PG、RADOS、librados、libcephfs、cephfs、rbd、radosgw、RGW、RESTful API、认证、授权、加密、纠删码、复制、快照、克隆、精简配置、iSCSI、Fibre Channel、NFS、CIFS、POSIX、监控、仪表板、管理、编排、自动化、集成、容器化、Kubernetes、Docker、虚拟化、云计算、AWS、Azure、Google Cloud、混合云、多云、存储集群、节点、磁盘、SSD、HDD、JBOD、SAN、NAS、网络、拓扑、故障域、恢复、弹性、负载均衡、缓存、压缩、去重、分层、性能调优、基准测试、测试、验证。</li></ol>',13)])])}const P=a(t,[["render",r]]);export{d as __pageData,P as default};
